  { date: "2024-06-24", desktop: { view: 132 }, mobile: { view: 180 } },
  { date: "2024-06-25", desktop: { view: 141 }, mobile: { view: 190 } },
  { date: "2024-06-26", desktop: { view: 434 }, mobile: { view: 380 } },
  { date: "2024-06-27", desktop: { view: 448 }, mobile: { view: 490 } },
  { date: "2024-06-28", desktop: { view: 149 }, mobile: { view: 200 } },
  { date: "2024-06-29", desktop: { view: 103 }, mobile: { view: 160 } },
  { date: "2024-06-30", desktop: { view: 446 }, mobile: { view: 400 } },
]

const chartConfig = {
  view: {
    label: "Page Views",
  },
  desktop: {
    label: "Desktop",
    color: "var(--chart-1)",
  },
  mobile: {
    label: "Mobile",
    color: "var(--chart-2)",
  },
} satisfies ChartConfig

const BarChartInteractive = () => {
  const isMobile = useIsMobile()

  const numTicks = () => {
    if (isMobile()) {
      return 4
    }
    return 9
  }

  const [activeChart, setActiveChart] =
    createSignal<keyof typeof chartConfig>("desktop")

  const keys = createMemo(() =>
    // @ts-expect-error

    Object.keys(data[0][activeChart()]).map((i) => ({ view: i })),
  )

  const y = createMemo(() =>
    // @ts-expect-error
    // eslint-disable-next-line solid/reactivity
    keys().map((i) => (d: DataRecord) => d[activeChart()][i.view]),
  )

  const total = createMemo(() => ({
    desktop: data.reduce((acc, curr) => acc + curr.desktop.view, 0),
    mobile: data.reduce((acc, curr) => acc + curr.mobile.view, 0),
  }))

  return (
    <Card class="py-0">
      <CardHeader class="flex flex-col items-stretch border-b p-0! sm:flex-row">
        <div class="flex flex-1 flex-col justify-center gap-1 px-6 pt-4 pb-3 sm:py-0!">
          <CardTitle>Bar Chart - Interactive</CardTitle>
          <CardDescription>
            Showing total visitors for the last 3 months
          </CardDescription>
        </div>
        <div class="flex">
          <For each={["desktop", "mobile"]}>
            {(key) => {
              const chart = key as keyof typeof chartConfig
              return (
                <button
                  type="button"
                  data-active={activeChart() === chart}
                  class="data-[active=true]:bg-muted/50 relative z-30 flex flex-1 flex-col justify-center gap-1 border-t px-6 py-4 text-left even:border-l sm:border-t-0 sm:border-l sm:px-8 sm:py-6"
                  onClick={() => setActiveChart(chart)}
                >
                  <span class="text-muted-foreground text-xs">
                    {chartConfig[chart].label}
                  </span>
                  <span class="text-lg leading-none font-bold sm:text-3xl">
                    {total()[key as keyof typeof total]}
                  </span>
                </button>
              )
            }}
          </For>
        </div>
      </CardHeader>
      <CardContent class="px-2 sm:p-6">
        <ChartContainer
          config={chartConfig}
          type="xy"
          data={data}
          class="aspect-auto"
          height={250}
          width={"100%"}
          yDomain={[0, Math.max(...data.map((d) => d.mobile.view + 50))]}
        >
          <VisStackedBar<DataRecord>
            x={(_, i) => i}
            y={y()}
            color={`var(--color-${activeChart()})`}
            barPadding={0.2}
          />
          <VisAxis<DataRecord>
            type="x"
            tickFormat={(d) => {
              const date = new Date(data[d as number].date)
              return date.toLocaleDateString("en-US", {
                month: "short",
                day: "numeric",
              })
            }}
            gridLine={false}
            tickLine={false}
            domainLine={false}
            numTicks={numTicks()}
          />
          <VisTooltip
            triggers={{
              [StackedBar.selectors.bar]: (d: DataRecord, x) => {
                const container = document.createElement("div")
                const Component = () => (
                  <ChartTooltipContent<Partial<DataRecord>, typeof chartConfig>
                    data={{
                      date: d.date,
                      // @ts-expect-error
                      [activeChart()]: d[activeChart()],
                    }}
                    x={x}
                    config={chartConfig}
                    labelKey="view"
                    nameKey="view"
                    labelFormatter={() =>
                      new Date(d.date).toLocaleDateString("en-US", {
                        month: "short",
                        day: "numeric",
                        year: "numeric",
                      })
                    }
                  />
                )
                render(() => <Component />, container)
                return container.innerHTML
              },
            }}
          />
        </ChartContainer>
      </CardContent>
    </Card>
  )
}

export default BarChartInteractive

