---
title: Data Table
description: Powerful table and datagrids built using TanStack Table.
link:
  doc: https://tanstack.com/table/latest/docs/introduction
---

<ComponentPreview name="data-table-demo">

```tsx file=<rootDir>/apps/docs/src/registry/examples/data-table-demo.tsx

```

</ComponentPreview>

## Introduction

Every data table or datagrid I've created has been unique. They all behave differently, have specific sorting and filtering requirements, and work with different data sources.

It doesn't make sense to combine all of these variations into a single component. If we do that, we'll lose the flexibility that [headless UI](https://tanstack.com/table/v8/docs/guide/introduction#what-is-headless-ui) provides.

So instead of a data-table component, I thought it would be more helpful to provide a guide on how to build your own.

We'll start with the basic `<Table />` component and build a complex data table from scratch.

**Tip:** If you find yourself using the same table in multiple places in your app, you can always extract it into a reusable component.

## Table of Contents

This guide will show you how to use [TanStack Table](https://tanstack.com/table) and the `<Table />` component to build your own custom data table. We'll cover the following topics:

- [Basic Table](#basic-table)
- [Row Actions](#row-actions)
- [Pagination](#pagination)
- [Sorting](#sorting)
- [Filtering](#filtering)
- [Visibility](#visibility)
- [Row Selection](#row-selection)

## Installation

1. Add the `<Table />` component to your project:

```bash
npx shadcn-solid@latest add table button dropdown-menu textfield checkbox
```

2. Add `tanstack/solid-table` dependency:

```bash
npm install @tanstack/solid-table
```

## Prerequisites

We are going to build a table to show tasks. Here's what our data looks like:

```tsx
type Task = {
  id: string
  code: string
  title: string
  status: "todo" | "in-progress" | "done" | "cancelled"
  label: "bug" | "feature" | "enhancement" | "documentation"
}

export const tasks: Task[] = [
  {
    id: "ptL0KpX_yRMI98JFr6B3n",
    code: "TASK-33",
    title: "We need to bypass the redundant AI interface!",
    status: "todo",
    label: "bug",
  },
  {
    id: "RsrTg_SmBKPKwbUlr7Ztv",
    code: "TASK-59",
    title:
      "Overriding the capacitor won't do anything, we need to generate the solid state JBOD pixel!",
    status: "in-progress",
    label: "feature",
  },
  // ...
]
```

## Project Structure

Start by creating the following file structure:

```txt
src
└── routes
    ├── _components
    │   ├── columns.tsx
    │   └── data-table.tsx
    └── index.tsx
```

- `columns.tsx` will contain our column definitions.
- `data-table.tsx` will contain our `<DataTable />` component.
- `index.tsx` is where we'll fetch data and render our table.

## Basic Table

Let's start by building a basic table.

<Step>

### Column Definitions

First, we'll define our columns.

```tsx title="src/routes/_components/columns.tsx" {1,13-26}
import type { ColumnDef } from "@tanstack/solid-table"

// This type is used to define the shape of our data.
// You can use a Zod or Validbot schema here if you want.
export type Task = {
  id: string
  code: string
  title: string
  status: "todo" | "in-progress" | "done" | "cancelled"
  label: "bug" | "feature" | "enhancement" | "documentation"
}

export const columns: ColumnDef<Task>[] = [
  {
    accessorKey: "code",
    header: "Task",
  },
  {
    accessorKey: "title",
    header: "Title",
  },
  {
    accessorKey: "status",
    header: "Status",
  },
]
```

### `<DataTable />` component

Next, we'll create a `<DataTable />` component to render our table.

```tsx title="src/routes/_components/data-table.tsx"
import { Accessor, For, Show, splitProps } from "solid-js"
import {
  createSolidTable,
  flexRender,
  getCoreRowModel,
  type ColumnDef,
} from "@tanstack/solid-table"

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"

type Props<TData, TValue> = {
  columns: ColumnDef<TData, TValue>[]
  data: Accessor<TData[] | undefined>
}

export const DataTable = <TData, TValue>(props: Props<TData, TValue>) => {
  const [local] = splitProps(props, ["columns", "data"])

  const table = createSolidTable({
    get data() {
      return local.data() || []
    },
    columns: local.columns,
    getCoreRowModel: getCoreRowModel(),
  })

  return (
    <div class="rounded-md border">
      <Table>
        <TableHeader>
          <For each={table.getHeaderGroups()}>
            {(headerGroup) => (
              <TableRow>
                <For each={headerGroup.headers}>
                  {(header) => {
                    return (
                      <TableHead>
                        {header.isPlaceholder
                          ? null
                          : flexRender(
                              header.column.columnDef.header,
                              header.getContext(),
                            )}
                      </TableHead>
                    )
                  }}
                </For>
              </TableRow>
            )}
          </For>
        </TableHeader>
        <TableBody>
          <Show
            when={table.getRowModel().rows?.length}
            fallback={
              <TableRow>
                <TableCell
                  colSpan={local.columns.length}
                  class="h-24 text-center"
                >
                  No results.
                </TableCell>
              </TableRow>
            }
          >
            <For each={table.getRowModel().rows}>
              {(row) => (
                <TableRow data-state={row.getIsSelected() && "selected"}>
                  <For each={row.getVisibleCells()}>
                    {(cell) => (
                      <TableCell>
                        {flexRender(
                          cell.column.columnDef.cell,
                          cell.getContext(),
                        )}
                      </TableCell>
                    )}
                  </For>
                </TableRow>
              )}
            </For>
          </Show>
        </TableBody>
      </Table>
    </div>
  )
}
```

### Render the table

Finally, we'll render our table in our index page.

```tsx title="src/routes/index.tsx" {29}
import { cache, createAsync, type RouteDefinition } from "@solidjs/router"

import { columns, type Task } from "./_components/columns"
import { DataTable } from "./_components/data-table"

const getData = cache(async (): Promise<Task[]> => {
  // Fetch data from your API here.
  return [
    {
      id: "ptL0KpX_yRMI98JFr6B3n",
      code: "TASK-33",
      title: "We need to bypass the redundant AI interface!",
      status: "todo",
      label: "bug",
    },
    // ...
  ]
}, "data")

export const route: RouteDefinition = {
  load: () => getData(),
}

const Home = () => {
  const data = createAsync(() => getData())

  return (
    <div class="w-full space-y-2.5">
      <DataTable columns={columns} data={data} />
    </div>
  )
}

export default Home
```

</Step>

