## Filtering

Add filter to the title. See the [filtering docs](https://tanstack.com/table/v8/docs/guide/filters) for more information on customizing filters.

### Update `<DataTable />`

```tsx title="src/routes/_components/data-table.tsx" {4-5,11,15-16,19-21,27-40}
//...
import {
  //...
  ColumnFiltersState,
  getFilteredRowModel,
} from "@tanstack/solid-table"
import { TextField, TextFieldRoot } from "~/components/ui/textfield"

export const DataTable = <TData, TValue>(props: Props<TData, TValue>) => {
  //...
  const [columnFilters, setColumnFilters] = createSignal<ColumnFiltersState>([])

  const table = createSolidTable({
    //...
    getFilteredRowModel: getFilteredRowModel(),
    onColumnFiltersChange: setColumnFilters,
    state: {
      //...
      get columnFilters() {
        return columnFilters()
      },
    },
  })

  return (
    <div>
      <div class="flex items-center py-4">
        <TextFieldRoot>
          <TextField
            placeholder="Filter title..."
            value={(table.getColumn("title")?.getFilterValue() as string) ?? ""}
            onInput={(event) =>
              table
                .getColumn("title")
                ?.setFilterValue(event.currentTarget.value)
            }
            class="max-w-sm"
          />
        </TextFieldRoot>
      </div>
      <div class="rounded-md border">...</div>
    </div>
  )
}
```

## Visibility

Adding column visibility using visibility API.

### Update `<DataTable />`

```tsx title="src/routes/_components/data-table.tsx" {4,19-21,25,28-30,38-63}
//...
import {
  //...
  VisibilityState,
} from "@tanstack/solid-table"
import { As } from "@kobalte/core"
import type { DropdownMenuTriggerProps } from "@kobalte/core/dropdown-menu"
import { Button } from "~/components/ui/button"

import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"

export const DataTable = <TData, TValue>(props: Props<TData, TValue>) => {
  //...
  const [columnVisibility, setColumnVisibility] = createSignal<VisibilityState>(
    {},
  )

  const table = createSolidTable({
    //...
    onColumnVisibilityChange: setColumnVisibility,
    state: {
      //...
      get columnVisibility() {
        return columnVisibility()
      },
    },
  })

  return (
    <div>
      <div class="flex items-center py-4">
        //...
        <DropdownMenu>
          <DropdownMenuTrigger
            as={(props: DropdownMenuTriggerProps) => (
              <Button {...props} variant="outline" class="ml-auto">
                Columns
              </Button>
            )}
          />
          <DropdownMenuContent>
            <For
              each={table
                .getAllColumns()
                .filter((column) => column.getCanHide())}
            >
              {(item) => (
                <DropdownMenuCheckboxItem
                  class="capitalize"
                  checked={item.getIsVisible()}
                  onChange={(value) => item.toggleVisibility(!!value)}
                >
                  {item.id}
                </DropdownMenuCheckboxItem>
              )}
            </For>
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
      <div class="rounded-md border">...</div>
    </div>
  )
}
```

## Row Selection

Next, we're going to add row selection to our table.

<Step>

### Update column definitions

```tsx title="src/routes/_components/columns.tsx" {2,5-28}
//...
import { Checkbox, CheckboxControl } from "@/components/ui/checkbox"

export const columns: ColumnDef<Task>[] = [
  {
    id: "select",
    header: ({ table }) => (
      <Checkbox
        indeterminate={table.getIsSomePageRowsSelected()}
        checked={table.getIsAllPageRowsSelected()}
        onChange={(value) => table.toggleAllPageRowsSelected(!!value)}
        aria-label="Select all"
      >
        <CheckboxControl />
      </Checkbox>
    ),
    cell: ({ row }) => (
      <Checkbox
        checked={row.getIsSelected()}
        onChange={(value) => row.toggleSelected(!!value)}
        aria-label="Select row"
      >
        <CheckboxControl />
      </Checkbox>
    ),
    enableSorting: false,
    enableHiding: false,
  },
  // ...
]
```

### Update `<DataTable />`

```tsx title="src/routes/_components/data-table.tsx" {5,9,12-14}
