  const [, rest] = splitProps(props as SidebarTriggerProps, [
    "class",
    "onClick",
  ])
  const { toggleSidebar, open } = useSidebar()

  const handleOnclick: JSX.EventHandlerUnion<HTMLButtonElement, MouseEvent> = (
